"use client";

// Automations tab of one client: a weekly or monthly report generated by itself,
// already shared, with the link ready to copy and send.

import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import { useTranslations } from "next-intl";
import { toast } from "sonner";
import { Check, Copy, FileText } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/dashboard/skeleton";
import { useHasPermission } from "@/hooks/use-permissions";
import { FREQUENCIES, isFrequency, type Frequency } from "@/lib/reportei/automation";
import { showDate, showDateTime } from "@/lib/reportei/format";
import { cn } from "@/lib/utils";

interface Automation {
  id: string;
  frequency: Frequency;
  active: boolean;
  lastRunOn: string | null;
  lastError: string | null;
  lastReport: { id: string; title: string; shareToken: string | null; createdAt: string } | null;
}

type State = { kind: "loading" } | { kind: "error" } | { kind: "ready"; automation: Automation | null };

export function AutomationPanel({ clientId, hasIntegrations }: { clientId: string; hasIntegrations: boolean }) {
  const t = useTranslations("Operational.reportei.automationsPanel");
  const canEdit = useHasPermission("operational", "tasks", "edit_boards");
  const [state, setState] = useState<State>({ kind: "loading" });
  const [frequency, setFrequency] = useState<Frequency>("weekly");
  const [saving, setSaving] = useState(false);
  const [copied, setCopied] = useState(false);

  const load = useCallback(async () => {
    const res = await fetch(`/api/operational/reportei/clients/${clientId}/automation`);
    if (!res.ok) return setState({ kind: "error" });
    const { automation } = (await res.json()) as { automation: Automation | null };
    if (automation && isFrequency(automation.frequency)) setFrequency(automation.frequency);
    setState({ kind: "ready", automation });
  }, [clientId]);

  useEffect(() => {
    // Initial fetch; setState happens after the await, not synchronously.
    void load();
  }, [load]);

  async function save(next: { frequency: Frequency; active: boolean }) {
    setSaving(true);
    try {
      const res = await fetch(`/api/operational/reportei/clients/${clientId}/automation`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(next),
      });
      if (!res.ok) return toast.error(t("saveError"));
      const { automation } = (await res.json()) as { automation: Automation };
      setFrequency(next.frequency);
      setState({ kind: "ready", automation });
      toast.success(t("saved"));
    } catch {
      toast.error(t("saveError"));
    } finally {
      setSaving(false);
    }
  }

  if (!hasIntegrations) return <p className="text-sm text-muted-foreground">{t("noIntegrations")}</p>;
  if (state.kind === "loading") return <Skeleton className="h-40" />;
  if (state.kind === "error") return <p className="text-sm text-red-500">{t("error")}</p>;

  const { automation } = state;
  const link = automation?.lastReport?.shareToken ? `${window.location.origin}/r/${automation.lastReport.shareToken}` : "";

  async function copy() {
    try {
      await navigator.clipboard.writeText(link);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error(t("copyError"));
    }
  }

  return (
    <div className="max-w-2xl space-y-5">
      <p className="text-sm text-muted-foreground">{t("intro")}</p>

      <div className="space-y-2" role="radiogroup" aria-label={t("frequencyLabel")}>
        <span className="text-sm font-medium text-foreground">{t("frequencyLabel")}</span>
        <div className="flex flex-wrap gap-2">
          {FREQUENCIES.map((f) => (
            <button
              key={f}
              type="button"
              role="radio"
              aria-checked={frequency === f}
              disabled={!canEdit || saving}
              onClick={() => (automation ? void save({ frequency: f, active: automation.active }) : setFrequency(f))}
              className={cn(
                "rounded-xl border px-4 py-2.5 text-left text-sm transition-colors disabled:opacity-60",
                frequency === f ? "border-primary bg-primary/10" : "border-border hover:bg-muted/50",
              )}
            >
              <span className="block font-medium text-foreground">{t(`freq_${f}`)}</span>
              <span className="block text-xs text-muted-foreground">{t(`freqHint_${f}`)}</span>
            </button>
          ))}
        </div>
      </div>

      {canEdit && (
        <div className="flex items-center gap-3">
          {!automation ? (
            <Button size="sm" disabled={saving} onClick={() => save({ frequency, active: true })}>
              {t("activate")}
            </Button>
          ) : (
            <Button size="sm" variant={automation.active ? "outline" : "default"} disabled={saving} onClick={() => save({ frequency: automation.frequency, active: !automation.active })}>
              {automation.active ? t("pause") : t("resume")}
            </Button>
          )}
          {automation && (
            <span className={cn("rounded-full px-2 py-0.5 text-[11px] font-medium", automation.active ? "bg-emerald-500/15 text-emerald-500" : "bg-muted text-muted-foreground")}>
              {automation.active ? t("statusOn") : t("statusOff")}
            </span>
          )}
        </div>
      )}

      {automation?.lastError && <p className="text-sm text-red-500">{t(`error_${automation.lastError}`)}</p>}

      {automation && (
        <section className="space-y-3 rounded-xl border border-border bg-card p-4">
          <h3 className="text-sm font-semibold text-foreground">{t("lastTitle")}</h3>
          {automation.lastReport ? (
            <>
              <Link href={`/operational/reportei/relatorios/${automation.lastReport.id}`} className="flex items-center gap-2 text-sm text-foreground hover:underline">
                <FileText className="h-4 w-4 shrink-0 text-primary" />
                <span className="truncate">{automation.lastReport.title}</span>
                <span className="shrink-0 text-xs text-muted-foreground">{showDateTime(automation.lastReport.createdAt)}</span>
              </Link>
              {link && (
                <div className="flex flex-wrap items-center gap-2">
                  <Input readOnly value={link} onFocus={(e) => e.currentTarget.select()} className="h-8 w-80 max-w-full text-xs" aria-label={t("linkLabel")} />
                  <Button variant="outline" size="sm" onClick={copy}>
                    {copied ? <Check className="mr-1.5 h-4 w-4" /> : <Copy className="mr-1.5 h-4 w-4" />}
                    {copied ? t("copied") : t("copy")}
                  </Button>
                </div>
              )}
              {!link && <p className="text-xs text-muted-foreground">{t("linkOff")}</p>}
            </>
          ) : (
            <p className="text-sm text-muted-foreground">{automation.lastRunOn ? t("lastRunNoReport", { date: showDate(automation.lastRunOn) }) : t("neverRan")}</p>
          )}
        </section>
      )}
    </div>
  );
}
